import Foundation

/// The two hand-made decisions about which series the dataset covers.
///
/// Everything else in `SeedList` is generated by `dataset-generator seed` and
/// rewritten on every run, so anything a person decides lives here instead.
enum SeedCuration {
    /// Picked by hand to span the shapes the analysis exists to describe —
    /// runs that hold their level, runs that fall off, runs that start slow and
    /// climb, runs that land their finale — rather than merely the most popular
    /// shows. Always seeded, ahead of everything discovered.
    static let handPickedIds: [Int] = [
        1396,  // Breaking Bad
        1398,  // The Sopranos
        1622,  // Supernatural
        1408,  // House
        1668,  // Friends
        1418,  // The Big Bang Theory
        60059,  // Better Call Saul
        1399,  // Game of Thrones
        66732,  // Stranger Things
        63174,  // Lucifer
        1438,  // The Wire
        4614,  // NCIS
        456,  // The Simpsons
        2316,  // The Office
        31917,
        62286,  // Fear the Walking Dead
        1402,  // The Walking Dead
        71712,  // The Good Doctor
        60625,  // Rick and Morty
        82856,  // The Mandalorian
        87108,  // Chernobyl
        76479,  // The Boys
        94605,  // Arcane
        85271,  // WandaVision
    ]

    /// Never seeded, whatever TMDB's listings say. For a series the genre
    /// filter lets through but which has no episode arc to analyse — a game
    /// show filed as Comedy, a news magazine filed as Documentary. Deleting
    /// its line from `SeedList` is not enough: the next `seed` run would put
    /// it straight back.
    static let excludedIds: Set<Int> = [
        114695,  // Marvel Studios Legends — recap clips, no episode arc
        1428,  // MythBusters — standalone experiments, no episode arc
        15826,  // 1000 Ways to Die — unconnected anthology of deaths
        32608,  // Ancient Aliens — hundreds of standalone talking-head episodes
        96815,  // Sex, Explained — standalone-topic explainer docuseries, no episode arc
        105288,  // Down to Earth with Zac Efron — standalone travel docuseries
        127700,  // Welcome to Earth — standalone adventure docuseries
        58957,  // Nathan for You — reality-format standalone segments
        94667,  // De viaje con los Derbez — travel reality
        83247,  // Haunted — anthology of unconnected true stories
        105177,  // Unsolved Mysteries — anthology of unrelated cases
        110290,  // Mums Make Porn — reality
        66185,  // The Story of God with Morgan Freeman — topic-per-episode docuseries
        129035,  // The Walking Dead: Origins — recap series
        90,  // Mayday — standalone air-disaster investigations, no episode arc
        34014,  // An Idiot Abroad — travel reality, standalone trips
        113178,  // Alien Worlds — standalone speculative-nature episodes
    ]
}
